// Development host. Allocation, Java execution, type checks, workers and GC are MASM.
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class BoomMultiArrayProbe {
    [StructLayout(LayoutKind.Sequential)] struct Context {public uint Kind,PC,Method,Depth;}
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode)] static extern IntPtr LoadLibraryExW(string p,IntPtr z,uint f);
    [DllImport("kernel32.dll",CharSet=CharSet.Ansi)] static extern IntPtr GetProcAddress(IntPtr m,string n);
    [DllImport("kernel32.dll")] static extern bool FreeLibrary(IntPtr m);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Create(ulong n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Bind(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Destroy(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Entry(ref Context c,[In] ulong[] args);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Type(uint id);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr New(IntPtr h,[In] ulong[] counts,IntPtr type,uint n,ref Context c);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Alloc(IntPtr h,ulong bytes,uint refs,ulong tag);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Roots(out uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Collect(IntPtr h,IntPtr roots,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint Release();
    static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
    static IntPtr Open(string p){IntPtr m=LoadLibraryExW(p,IntPtr.Zero,0x1100);Check(m!=IntPtr.Zero,"Multiarray module load failed");return m;}
    static T Fn<T>(IntPtr m,string n){IntPtr p=GetProcAddress(m,n);Check(p!=IntPtr.Zero,"Missing "+n);return Marshal.GetDelegateForFunctionPointer<T>(p);}
    static void Close(IntPtr m,IntPtr h){IntPtr p=GetProcAddress(m,"boom_release_trace_pool");if(p!=IntPtr.Zero)Check(Marshal.GetDelegateForFunctionPointer<Release>(p)()==0,"Multiarray Java frames active");if(h!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(h)!=0,"Multiarray heap cleanup failed");Check(FreeLibrary(m),"Multiarray module cleanup failed");}
    static IntPtr Invoke(Entry f,ulong n){var c=new Context();IntPtr p=new IntPtr(unchecked((long)f(ref c,new ulong[]{n})));Check(c.Kind==0&&c.Depth==0&&p!=IntPtr.Zero,"Multiarray fixture failed: "+c.Kind);return p;}
    static int Reachable(IntPtr roots,uint n){var live=new HashSet<IntPtr>();var work=new Stack<IntPtr>();for(int i=0;i<n;i++)work.Push(Marshal.ReadIntPtr(roots,i*8));while(work.Count!=0){IntPtr p=work.Pop();if(p==IntPtr.Zero||!live.Add(p))continue;uint flags=unchecked((uint)Marshal.ReadInt32(p,-24)),refs=unchecked((uint)Marshal.ReadInt32(p,-20));long bytes=Marshal.ReadInt64(p,-16);Check((flags&0xfffffffd)==0xb00b0001&&bytes>=0&&refs<=(ulong)bytes/8&&live.Count<1048576,"Malformed multiarray root graph");for(int i=0;i<refs;i++)work.Push(Marshal.ReadIntPtr(p,i*8));}return live.Count;}
    static void GC(IntPtr m,IntPtr h,params IntPtr[] extra){IntPtr roots=Fn<Roots>(m,"boom_get_static_roots")(out uint n),all=Marshal.AllocHGlobal(checked(((int)n+extra.Length)*8));try{for(int i=0;i<n;i++)Marshal.WriteIntPtr(all,i*8,Marshal.ReadIntPtr(roots,i*8));for(int i=0;i<extra.Length;i++)Marshal.WriteIntPtr(all,((int)n+i)*8,extra[i]);int expected=Reachable(all,n+(uint)extra.Length);Check(Fn<Collect>(m,"boom_heap_collect")(h,all,n+(uint)extra.Length)!=ulong.MaxValue&&Marshal.ReadInt64(h,56)==expected,"Multiarray partial/complete graph lost or leaked during GC");}finally{Marshal.FreeHGlobal(all);}}
    static int Tree(IntPtr p,IntPtr type,int[] counts,int level,HashSet<IntPtr> seen){Check(p!=IntPtr.Zero&&seen.Add(p),"Array allocation shared a node");Check(Marshal.ReadInt32(type,8)==3,"Invalid expected array type");IntPtr component=Marshal.ReadIntPtr(type,16);int kind=Marshal.ReadInt32(component,8),n=counts[level];long tag;int shift,refs;
        if(kind==0){int primitive=Marshal.ReadInt32(component,12);int[] tags={260,264,261,265,266,267,262,263},shifts={0,0,1,1,2,3,2,3};Check(primitive>=0&&primitive<8,"Invalid primitive type");tag=tags[primitive];shift=shifts[primitive];refs=0;}
        else{tag=type.ToInt64();shift=3;refs=n;}
        Check(Marshal.ReadInt64(p,-8)==tag&&Marshal.ReadInt64(p,-16)==((long)n<<shift)&&Marshal.ReadInt32(p,-20)==refs,"Multiarray tag, length or reference prefix differs");
        int total=1;if(level+1<counts.Length){for(int i=0;i<n;i++)total+=Tree(Marshal.ReadIntPtr(p,i*8),component,counts,level+1,seen);}else{long bytes=Marshal.ReadInt64(p,-16);for(int i=0;i<bytes;i++)Check(Marshal.ReadByte(p,i)==0,"New array leaf was not zero initialized");}return total;
    }
    public static void Native(string dll,string runtime,uint[] ids){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{
        Check(ids.Length==12,"Missing factory type IDs");h=Fn<Create>(m,"boom_heap_create")(2*1024*1024);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Multiarray heap setup failed");var entry=Fn<Entry>(m,"boom_entry");var get=Fn<Type>(m,"boom_get_type_descriptor");var alloc=Fn<Alloc>(r,"boom_heap_alloc");var create=Fn<New>(m,"boom_typed_multi_new");
        for(uint which=0;which<12;which++){long before=Marshal.ReadInt64(h,56);IntPtr p=Invoke(entry,which),type=get(ids[which]);int[] shape=which==8||which==11?new int[]{2,3,4}:new int[]{2,3};int objects=Tree(p,type,shape,0,new HashSet<IntPtr>());Check(Marshal.ReadInt64(h,56)==before+objects,"Multiarray allocated beyond requested tree");GC(m,h,p);Tree(p,type,shape,0,new HashSet<IntPtr>());GC(m,h);}
        IntPtr expectedType=get(ids[4]);long baseline=Marshal.ReadInt64(h,56);var c=new Context{Kind=9,PC=17,Method=23,Depth=3};Check(create(IntPtr.Zero,null,IntPtr.Zero,0,ref c)==IntPtr.Zero&&c.Kind==9&&c.PC==17&&c.Method==23&&c.Depth==3,"Multiarray changed pending context");
        foreach(ulong[] counts in new ulong[][]{new ulong[]{0,ulong.MaxValue},new ulong[]{2,0xffffffff},new ulong[]{0xffffffff,0}}){c=new Context{PC=17,Method=23};Check(create(h,counts,expectedType,2,ref c)==IntPtr.Zero&&c.Kind==2&&c.PC==17&&c.Method==23&&Marshal.ReadInt64(h,56)==baseline,"Negative dimension was not checked before allocation");}
        foreach(uint dims in new uint[]{0,3,256}){c=new Context();Check(create(h,new ulong[]{1,1,1},expectedType,dims,ref c)==IntPtr.Zero&&c.Kind==7&&Marshal.ReadInt64(h,56)==baseline,"Invalid rank/dimensions accepted");}
        IntPtr bad=Marshal.AllocHGlobal(40);try{byte[] data=new byte[40];Marshal.Copy(expectedType,data,0,40);foreach(int offset in new int[]{0,4,8,16}){Marshal.Copy(data,0,bad,40);if(offset==16)Marshal.WriteIntPtr(bad,offset,IntPtr.Zero);else Marshal.WriteInt32(bad,offset,offset==8?1:7);c=new Context();Check(create(h,new ulong[]{2,3},bad,2,ref c)==IntPtr.Zero&&c.Kind==7&&Marshal.ReadInt64(h,56)==baseline,"Malformed allocation metadata accepted");}}finally{Marshal.FreeHGlobal(bad);}
        // Reserve one 672-byte hole. The root and first child fit, second does not.
        IntPtr hole=alloc(h,640,0,264);Check(hole!=IntPtr.Zero,"Multiarray partial OOM hole failed");var keep=new List<IntPtr>();IntPtr filler;while((filler=alloc(h,4096,0,264))!=IntPtr.Zero)keep.Add(filler);while((filler=alloc(h,0,0,264))!=IntPtr.Zero)keep.Add(filler);GC(m,h,keep.ToArray());long full=Marshal.ReadInt64(h,56);c=new Context{PC=17,Method=23};Check(create(h,new ulong[]{2,128},expectedType,2,ref c)==IntPtr.Zero&&c.Kind==3&&c.PC==17&&c.Method==23&&Marshal.ReadInt64(h,56)==full+2,"Partial multiarray OOM path not reached");GC(m,h,keep.ToArray());Check(Marshal.ReadInt64(h,56)==full,"Unreturned partial tree retained");GC(m,h);c=new Context();IntPtr recovered=create(h,new ulong[]{2,128},expectedType,2,ref c);Check(c.Kind==0&&recovered!=IntPtr.Zero,"Multiarray allocation did not recover after GC");Tree(recovered,expectedType,new int[]{2,128},0,new HashSet<IntPtr>());GC(m,h,recovered);
    }finally{Close(m,h);Check(FreeLibrary(r),"Multiarray runtime cleanup failed");}}
    public static void Deep(string dll,uint id){IntPtr m=Open(dll),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(1024*1024);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Deep array setup failed");IntPtr p=Invoke(Fn<Entry>(m,"boom_entry"),0),type=Fn<Type>(m,"boom_get_type_descriptor")(id);int[] counts=new int[255];for(int i=0;i<254;i++)counts[i]=1;Check(Tree(p,type,counts,0,new HashSet<IntPtr>())==255,"255-dimensional tree shape differs");GC(m,h,p);Tree(p,type,counts,0,new HashSet<IntPtr>());}finally{Close(m,h);}}
    public static void FullHeap(string dll,string runtime){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(65536);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Full multiarray heap setup failed");var entry=Fn<Entry>(m,"boom_entry");for(ulong i=0;i<4;i++){var c=new Context();Check(entry(ref c,new ulong[]{i})==2&&c.Kind==0,"Full-heap warmup failed");}GC(m,h);var alloc=Fn<Alloc>(r,"boom_heap_alloc");while(alloc(h,4096,0,267)!=IntPtr.Zero){}while(alloc(h,0,0,267)!=IntPtr.Zero){}long full=Marshal.ReadInt64(h,56);for(ulong i=0;i<256;i++){var c=new Context();Check(entry(ref c,new ulong[]{i})==((i&1)==0?2UL:97UL)&&c.Kind==0&&c.Depth==0&&Marshal.ReadInt64(h,56)==full,"Java multiarray OOM catch changed state/count");}GC(m,h);}finally{Close(m,h);Check(FreeLibrary(r),"Full-heap runtime cleanup failed");}}
}
